head.script:
// https://inswave01.atlassian.net/browse/WAEA-1212
// ===== 리턴 값 출력 영역 (body_bottom.xml inline 복사) =====
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};



scwin.onpageload = function () {
    tbx_return.setValue("");

    // Body Column 화면 스타일(배경색 / 글꼴 크기 13px) 지정
    //  · Column 의 인라인 style 속성은 useStyle 적용 대상이 아니므로 setColumnStyle 로 지정한다.
    target1.setColumnStyle(0, "background-color", "#E2EFDA");
    target1.setColumnStyle(0, "font-size", "13px");
    target1.setColumnStyle(1, "background-color", "#E2EFDA");
    target1.setColumnStyle(1, "font-size", "13px");
    target1.setColumnStyle(2, "background-color", "#DDEBF7");
    target1.setColumnStyle(2, "font-size", "13px");
    target1.setColumnStyle(3, "background-color", "#DDEBF7");
    target1.setColumnStyle(3, "font-size", "13px");
};



// setFontSize 미전달 (생략)
scwin.btn_base_onclick = function (e) {
    target1.advancedExcelDownload({
        "fileName" : "base",
        "extension" : "xlsx",
        "useStyle" : "true",
        "useSubTotal" : "true",
        "useSubTotalColumnClass" : "true"
    });

    scwin.setReturnValue("호출 : useStyle=true / setFontSize 생략");
};



// setFontSize = true
scwin.btn_true_onclick = function (e) {
    target1.advancedExcelDownload({
        "fileName" : "fs_true",
        "extension" : "xlsx",
        "useStyle" : "true",
        "useSubTotal" : "true",
        "useSubTotalColumnClass" : "true",
        "setFontSize" : "true"
    });

    scwin.setReturnValue("호출 : useStyle=true / setFontSize=true");
};



// setFontSize = false
scwin.btn_false_onclick = function (e) {
    target1.advancedExcelDownload({
        "fileName" : "fs_false",
        "extension" : "xlsx",
        "useStyle" : "true",
        "useSubTotal" : "true",
        "useSubTotalColumnClass" : "true",
        "setFontSize" : "false"
    });

    scwin.setReturnValue("호출 : useStyle=true / setFontSize=false");
};
